using Microsoft.EntityFrameworkCore;using System.Net.Http;using System.Drawing;
namespace TraSua;
public record PayConfig{public string BankId{get;set;}="970436";public string AccountNo{get;set;}="0000000000";public string AccountName{get;set;}="QUAN TRA SUA";public string Template{get;set;}="compact2";public string ShopName{get;set;}="Trà sữa";}
public class DanhMucMon{public int MaDM{get;set;}public string TenDM{get;set;}="";public List<MonUong> MonUongs{get;set;}=[];public override string ToString()=>TenDM;}public class MonUong{public int MaMon{get;set;}public string TenMon{get;set;}="";public decimal GiaBan{get;set;}public bool DangBan{get;set;}public int MaDM{get;set;}public DanhMucMon? DanhMucMon{get;set;}public override string ToString()=>TenMon;}public class HoaDon{public int MaHD{get;set;}public DateTime NgayLap{get;set;}public decimal TongTien{get;set;}public string HinhThucTT{get;set;}="";public bool DaThanhToan{get;set;}public List<ChiTietHoaDon> ChiTiets{get;set;}=[];}public class ChiTietHoaDon{public int MaHD{get;set;}public int MaMon{get;set;}public int SoLy{get;set;}public decimal DonGia{get;set;}public HoaDon? HoaDon{get;set;}public MonUong? MonUong{get;set;}}
public class TeaContext(string cs):DbContext{public DbSet<DanhMucMon> DanhMucMons=>Set<DanhMucMon>();public DbSet<MonUong> MonUongs=>Set<MonUong>();public DbSet<HoaDon> HoaDons=>Set<HoaDon>();public DbSet<ChiTietHoaDon> ChiTietHoaDons=>Set<ChiTietHoaDon>();protected override void OnConfiguring(DbContextOptionsBuilder b)=>b.UseSqlServer(cs);protected override void OnModelCreating(ModelBuilder b){b.Entity<DanhMucMon>().ToTable("DanhMucMon").HasKey(x=>x.MaDM);b.Entity<MonUong>().ToTable("MonUong").HasKey(x=>x.MaMon);b.Entity<MonUong>().HasOne(x=>x.DanhMucMon).WithMany(x=>x.MonUongs).HasForeignKey(x=>x.MaDM);b.Entity<HoaDon>().ToTable("HoaDon").HasKey(x=>x.MaHD);b.Entity<ChiTietHoaDon>().ToTable("ChiTietHoaDon").HasKey(x=>new{x.MaHD,x.MaMon});b.Entity<ChiTietHoaDon>().HasOne(x=>x.HoaDon).WithMany(x=>x.ChiTiets).HasForeignKey(x=>x.MaHD);b.Entity<ChiTietHoaDon>().HasOne(x=>x.MonUong).WithMany().HasForeignKey(x=>x.MaMon);}}
public sealed class MainForm:Form{static readonly HttpClient http=new(){Timeout=TimeSpan.FromSeconds(12)};readonly TeaContext db;readonly PayConfig pay;readonly ComboBox cats=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=140},menuCat=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=130},items=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=220};readonly NumericUpDown qty=new(){Minimum=1,Maximum=100,Value=1};readonly DataGridView grid=new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true};readonly DataGridView menuGrid=new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,SelectionMode=DataGridViewSelectionMode.FullRowSelect};readonly List<CartLine> cart=[];readonly Label sum=new(){AutoSize=true,Font=new Font("Segoe UI",13,FontStyle.Bold)},transfer=new(){AutoSize=true};readonly PictureBox qr=new(){Width=280,Height=280,SizeMode=PictureBoxSizeMode.Zoom};readonly DateTimePicker day=new(){Format=DateTimePickerFormat.Short};readonly TextBox dish=new(){Width=150};readonly NumericUpDown price=new(){Maximum=1000000,Increment=1000};readonly CheckBox selling=new(){Text="Đang bán",Checked=true};record CartLine(int MaMon,string TenMon,int SoLy,decimal DonGia){public decimal ThanhTien=>SoLy*DonGia;}
public MainForm(string cs,PayConfig p){db=new(cs);pay=p;Text="Bán hàng quán trà sữa";Width=1200;Height=800;cats.DataSource=db.DanhMucMons.AsNoTracking().ToList();menuCat.DataSource=db.DanhMucMons.AsNoTracking().ToList();cats.SelectedIndexChanged+=(_,_)=>LoadMenu();menuCat.SelectedIndexChanged+=(_,_)=>LoadMenu();var tabs=new TabControl{Dock=DockStyle.Fill};var sales=new TabPage("Bán hàng");var tools=new FlowLayoutPanel{Dock=DockStyle.Top,Height=105};tools.Controls.AddRange([new Label{Text="Danh mục"},menuCat,items,qty,Btn("Thêm vào đơn",AddCart),Btn("Xóa dòng",RemoveCart),Btn("Thanh toán chuyển khoản",async()=>await MakeQr()),Btn("Tiền mặt",()=>SaveBill("Tiền mặt",false)),Btn("Đã nhận tiền",()=>SaveBill("Chuyển khoản",true)),sum,transfer,qr]);grid.DataSource=cart;sales.Controls.Add(grid);sales.Controls.Add(tools);var menu=new TabPage("Thực đơn");var mp=new FlowLayoutPanel{Dock=DockStyle.Top,Height=70};mp.Controls.AddRange([new Label{Text="Danh mục lọc"},cats,new Label{Text="Tên món"},dish,new Label{Text="Giá"},price,selling,Btn("Thêm món",AddDish),Btn("Sửa món",EditDish),Btn("Xóa món",DeleteDish)]);var mg=menuGrid;cats.SelectedIndexChanged+=(_,_)=>LoadDishes(mg);dish.TextChanged+=(_,_)=>LoadDishes(mg);menu.Controls.Add(mg);menu.Controls.Add(mp);var bills=new TabPage("Hóa đơn");var bg=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true};var rev=new Label{Dock=DockStyle.Bottom,Height=30};day.ValueChanged+=(_,_)=>LoadBills(bg,rev);bills.Controls.Add(bg);bills.Controls.Add(rev);bills.Controls.Add(day);tabs.TabPages.AddRange([sales,menu,bills]);Controls.Add(tabs);LoadMenu();LoadDishes(mg);LoadBills(bg,rev);}
Button Btn(string s,Action a){var b=new Button{Text=s,AutoSize=true};b.Click+=async(_,_)=>a();return b;}void LoadMenu(){if(menuCat.SelectedItem is DanhMucMon c)items.DataSource=db.MonUongs.Where(x=>x.MaDM==c.MaDM&&x.DangBan).ToList();}void AddCart(){if(items.SelectedItem is not MonUong x)return;var i=cart.FindIndex(z=>z.MaMon==x.MaMon);if(i<0)cart.Add(new(x.MaMon,x.TenMon,(int)qty.Value,x.GiaBan));else cart[i]=cart[i] with{SoLy=cart[i].SoLy+(int)qty.Value};RefreshCart();}void RemoveCart(){if(grid.CurrentRow?.DataBoundItem is CartLine x)cart.Remove(x);RefreshCart();}void RefreshCart(){grid.DataSource=null;grid.DataSource=cart.ToList();sum.Text=$"Tổng tiền: {cart.Sum(x=>x.ThanhTien):N0} đ";}
async Task MakeQr(){if(cart.Count==0)return;try{var b=Btn("",()=>{});var uri=$"https://img.vietqr.io/image/{Uri.EscapeDataString(pay.BankId)}-{Uri.EscapeDataString(pay.AccountNo)}-{Uri.EscapeDataString(pay.Template)}.png?amount={cart.Sum(x=>x.ThanhTien)}&addInfo={Uri.EscapeDataString("TRASUA HDMOI")}&accountName={Uri.EscapeDataString(pay.AccountName)}";var bytes=await http.GetByteArrayAsync(uri);using var ms=new MemoryStream(bytes);qr.Image=Image.FromStream(ms);transfer.Text=$"{pay.AccountName} | {pay.AccountNo} | {cart.Sum(x=>x.ThanhTien):N0} đ | TRASUA HDMOI";Serilog.Log.Information("QR created for amount {Amount}; account masked",cart.Sum(x=>x.ThanhTien));}catch(Exception e){Serilog.Log.Error(e,"VietQR image request failed");transfer.Text=$"Không tải được QR. Chuyển khoản tay: {pay.AccountName} - {pay.AccountNo}; số tiền {cart.Sum(x=>x.ThanhTien):N0} đ; nội dung TRASUA HDMOI";MessageBox.Show("Không tải được QR; khách có thể chuyển khoản tay hoặc chọn tiền mặt.");}}
void SaveBill(string method,bool paid){if(cart.Count==0){MessageBox.Show("Giỏ hàng đang trống.");return;}using var tx=db.Database.BeginTransaction();try{var bill=new HoaDon{NgayLap=DateTime.Now,TongTien=cart.Sum(x=>x.ThanhTien),HinhThucTT=method,DaThanhToan=paid};foreach(var l in cart)bill.ChiTiets.Add(new(){MaMon=l.MaMon,SoLy=l.SoLy,DonGia=l.DonGia});db.Add(bill);db.SaveChanges();tx.Commit();cart.Clear();RefreshCart();LoadBills(new DataGridView(),new Label());MessageBox.Show($"Đã lưu hóa đơn #{bill.MaHD}.");}catch(Exception e){tx.Rollback();Serilog.Log.Error(e,"Save bill failed");MessageBox.Show("Không lưu được hóa đơn.");}}
void LoadDishes(DataGridView g){var q=db.MonUongs.Include(x=>x.DanhMucMon).AsNoTracking().AsQueryable();if(cats.SelectedItem is DanhMucMon c)q=q.Where(x=>x.MaDM==c.MaDM);if(dish.Text!="")q=q.Where(x=>x.TenMon.Contains(dish.Text));g.DataSource=q.Select(x=>new{x.MaMon,x.TenMon,x.GiaBan,x.DangBan,DanhMuc=x.DanhMucMon!.TenDM}).ToList();}void AddDish(){if(cats.SelectedItem is not DanhMucMon c||dish.Text.Trim()=="")return;db.Add(new MonUong{TenMon=dish.Text.Trim(),GiaBan=price.Value,DangBan=selling.Checked,MaDM=c.MaDM});db.SaveChanges();LoadDishes(menuGrid);}void EditDish(){if(menuGrid.CurrentRow==null)return;int id=Convert.ToInt32(menuGrid.CurrentRow.Cells["MaMon"].Value);var x=db.MonUongs.Find(id);if(x==null)return;if(dish.Text.Trim()==""){MessageBox.Show("Nhập tên món.");return;}x.TenMon=dish.Text.Trim();x.GiaBan=price.Value;x.DangBan=selling.Checked;if(cats.SelectedItem is DanhMucMon c)x.MaDM=c.MaDM;db.SaveChanges();LoadDishes(menuGrid);}void DeleteDish(){if(menuGrid.CurrentRow==null)return;int id=Convert.ToInt32(menuGrid.CurrentRow.Cells["MaMon"].Value);var x=db.MonUongs.Find(id);if(x==null)return;if(MessageBox.Show("Xóa món đã chọn?","Xác nhận",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;try{db.Remove(x);db.SaveChanges();LoadDishes(menuGrid);}catch(Exception e){Serilog.Log.Error(e,"Delete menu item failed");MessageBox.Show("Không thể xóa món đã được dùng trong hóa đơn.");}}void LoadBills(DataGridView g,Label total){try{var d=day.Value.Date;var bills=db.HoaDons.Where(x=>x.NgayLap.Date==d).OrderByDescending(x=>x.NgayLap).ToList();g.DataSource=bills.Select(x=>new{x.MaHD,x.NgayLap,x.HinhThucTT,x.TongTien}).ToList();total.Text=$"Doanh thu ngày: {bills.Where(x=>x.DaThanhToan).Sum(x=>x.TongTien):N0} đ";}catch{}}}

